package com.andye.warmod.antiair.client;
import com.andye.warmod.antiair.AntiAirFlightPhase;import com.andye.warmod.antiair.client.render.AntiAirVisualGeometry;import com.andye.warmod.icbm.client.render.IcbmLongRangeRenderContext;import com.mojang.blaze3d.vertex.*;import net.minecraft.util.Mth;
public final class AntiAirThrustRenderer{private AntiAirThrustRenderer(){}public static void render(PoseStack.Pose p,VertexConsumer b,AntiAirFlightPhase phase,long seed,double time,IcbmLongRangeRenderContext.Lod lod){float scale=phase==AntiAirFlightPhase.IGNITION?.55F:phase==AntiAirFlightPhase.INTERCEPT?.58F:1F;float flicker=(float)(.92+.08*Math.sin(time*2.7+(seed&1023)*.031));float nozzle=(float)AntiAirVisualGeometry.nozzleExitOffset().y;plume(p,b,nozzle,.075F,.72F*scale*flicker,255,250,195,245);plume(p,b,nozzle-.02F,.14F,1.45F*scale*flicker,255,132,28,190);if(lod==IcbmLongRangeRenderContext.Lod.NEAR||lod==IcbmLongRangeRenderContext.Lod.MEDIUM)plume(p,b,nozzle-.04F,.10F,2.35F*scale*flicker,225,215,180,105);}private static void plume(PoseStack.Pose p,VertexConsumer b,float top,float radius,float length,int r,int g,int bl,int a){for(int q=0;q<2;q++){float angle=q*Mth.HALF_PI,c=Mth.cos(angle),s=Mth.sin(angle);v(p,b,-c*radius,top,-s*radius,r,g,bl,a);v(p,b,c*radius,top,s*radius,r,g,bl,a);v(p,b,c*.012F,top-length,s*.012F,r,g,bl,0);v(p,b,-c*.012F,top-length,-s*.012F,r,g,bl,0);}}private static void v(PoseStack.Pose p,VertexConsumer b,float x,float y,float z,int r,int g,int bl,int a){b.addVertex(p,x,y,z).setColor(r,g,bl,a).setUv(0,0).setOverlay(0).setLight(0xF000F0).setNormal(p,0,1,0);}}
